import {TABLES,CLUB,cardName,handValue} from './club-catalog.mjs?v=38';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createClubUI(api){
 let data=null,table=1,busy=false,polling=false,last=0,error='',signature='';const hud=document.createElement('section');hud.className='club-hud hidden';hud.setAttribute('aria-label','Casino controls');hud.innerHTML='<div><small>LAST HAND / GRAND CASINO</small><strong>Welcome to the grand room.</strong><span id="clubChipCount">Solo visit · explore the casino</span></div><nav aria-label="Club actions"><button id="clubTables">CARD TABLES</button><button data-club-area="lounge">LOUNGE</button><button data-club-area="bar">THE LATE CUP</button><button id="clubJoin">JOIN PLAYERS</button><button id="clubPhoto">PHOTO</button><button id="clubExit">LEAVE CASINO</button></nav><button id="clubInteract">EXPLORE THE FLOOR</button>';document.body.append(hud);
 const entrance=document.createElement('button');entrance.id='clubEntrance';entrance.className='club-entrance hidden';entrance.textContent='E · ENTER CASINO';entrance.onclick=()=>api.enter();document.body.append(entrance);
 const isOpen=()=>!!document.getElementById('clubTableDialog')&&!document.getElementById('modalRoot').classList.contains('hidden');
 async function request(path='',body){const r=await fetch('/api/club'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'content-type':'application/json'}:undefined,body:body?JSON.stringify({...body,session:api.session()}):undefined,signal:AbortSignal.timeout(9000)});const result=await r.json();if(!r.ok)throw Error(result.error||'The club is unavailable. Try again.');return result;}
 async function load(){data=await request();return data;}
 const btn=(title,action,disabled=false)=>'<button data-card-action="'+action+'" '+(busy||disabled?'disabled':'')+'>'+title+'</button>';
 const cards=(hand=[])=>'<div class="club-cards">'+hand.map(n=>'<span class="playing-card '+(n===null?'card-back':Math.floor(n/13)===1||Math.floor(n/13)===2?'card-red':'')+'" aria-label="'+esc(cardName(n))+'">'+(n===null?'G':esc(cardName(n)))+'</span>').join('')+'</div>';
 function render(){
  const t=data?.tables.find(t=>t.id===table),me=t?.seats.find(p=>p.id===data.playerId),playing=t?.phase==='playing';signature=JSON.stringify([t,data?.account,error,busy]);
  api.modal('<div id="clubTableDialog" class="club-dialog"><button class="modal-close" data-close aria-label="Close card table">×</button><header><small>LAST HAND / FREE PLAY</small><h2 id="dialogTitle">'+TABLES.find(t=>t.id===table).name.toUpperCase()+'</h2><div><b>'+ (data?.account.chips??'…')+' CHIPS</b><span>10 per hand · 4 seats</span></div></header>'+(error?'<p class="life-error" role="alert">'+esc(error)+'</p>':'')+(t?'<div class="club-felt"><div class="club-dealer"><small>DEALER '+(playing?'· ONE CARD HIDDEN':t.dealer.length?'· '+handValue(t.dealer):'· READY WHEN YOU ARE')+'</small>'+cards(t.dealer)+'</div><div class="club-seats">'+Array.from({length:4},(_,i)=>{const p=t.seats[i];return '<article class="club-seat '+(p?.id===data.playerId?'my-seat':'')+'"><strong>'+esc(p?.name||'OPEN SEAT')+(p?.id===data.playerId?' / YOU':'')+'</strong>'+cards(p?.hand)+'<span>'+esc(p?(p.result|| (p.status==='ready'?'10 chips in · ready':p.hand.length?handValue(p.hand)+' · '+p.status:'Watching this table')):'Bring a friend')+'</span></article>';}).join('')+'</div></div><div class="club-actions">'+(!me?btn('TAKE A SEAT','sit',playing||t.seats.length>=4):playing?me.status==='playing'?btn('HIT · ANOTHER CARD','hit')+btn('STAND · KEEP MY HAND','stand'):'<strong>Waiting for the other hands…</strong>':btn(me.status==='ready'?'10 CHIPS IN':'PLAY · 10 FREE CHIPS','ready',me.status==='ready'||data.account.chips<10)+(me.status==='ready'?btn('DEAL READY PLAYERS','deal'):'')+btn('LEAVE SEAT','leave'))+'</div>':'<p>Opening the table…</p>')+'<details><summary>HOW TO PLAY</summary><p>Get closer to 21 than the dealer without going over. Aces count as 1 or 11. Face cards count as 10. Ready players join when someone selects Deal; wait for your friends to ready up first.</p><p>The dealer stands on all 17s. Wins return 20 chips including your 10-chip stake; ties return 10. All wins pay the same, including a two-card 21. No splitting, doubling or insurance. A hand lasts up to 60 seconds; unfinished hands automatically stand.</p></details><footer><p>Free chips are only for playing cards here. They cannot be bought, transferred, redeemed or exchanged for items or GETAWAY.</p>'+btn('DAILY TOP-UP TO 500','chips',!data||data.account.gift_day===data.day)+'</footer></div>',true);
  document.getElementById('modalRoot').classList.add('club-shade');document.querySelectorAll('[data-card-action]').forEach(b=>b.onclick=()=>act(b.dataset.cardAction));
 }
 async function act(action){if(busy)return;busy=true;error='';render();try{if(action==='sit')await api.sync();const expectedRound=data.tables.find(t=>t.id===table).round;await load();let t=data.tables.find(t=>t.id===table);try{await request(action==='chips'?'/chips':'/table',action==='chips'?{}:{table,action,round:expectedRound,revision:t.revision});}catch(e){if(e.message!=='The table changed. Try again.')throw e;await load();t=data.tables.find(t=>t.id===table);await request('/table',{table,action,round:expectedRound,revision:t.revision});}}catch(e){error=e.message;}finally{try{await load();}catch(e){error=e.message;}busy=false;if(isOpen())render();}}
 async function open(id=1){if(!api.connected()){joinPrompt();return;}table=id;error='';api.pause();render();try{await api.sync();await load();}catch(e){error=e.message;}if(isOpen())render();}
 function interact(){const n=api.scene()?.nearest();if(!n)return;if(n.id==='exit')api.exit();else if(n.id==='lounge'||n.id==='bar'){if(api.connected())api.chat();else joinPrompt();}else void open(n.id);}
 function update(){const s=api.state(),inside=s.mode==='club';document.body.classList.toggle('in-social-club',inside);const near=['driving','walking'].includes(s.mode)&&Math.hypot(s.x-CLUB.x,s.z-CLUB.z)<CLUB.radius&&Math.abs(s.speed||0)<2;entrance.classList.toggle('hidden',!near||s.paused);hud.classList.toggle('hidden',!inside||s.paused||api.photoActive());if(!inside)return;const n=api.scene()?.nearest();document.getElementById('clubInteract').disabled=!n;document.getElementById('clubInteract').textContent=n?'E · '+n.label:'WALK TO A TABLE · WASD OR CLICK THE FLOOR';document.getElementById('clubChipCount').textContent=api.connected()?(data?data.account.chips+' FREE CHIPS · ':'')+'NEIGHBORHOOD '+api.room():'SOLO VISIT · JOIN PLAYERS FOR SHARED TABLES';document.getElementById('clubJoin').classList.toggle('hidden',api.connected());
  if(api.connected()&&!polling&&!busy&&Date.now()-last>(isOpen()?1600:6000)&&!document.hidden){last=Date.now();polling=true;void load().then(()=>{if(isOpen()&&!busy){const t=data.tables.find(t=>t.id===table);if(signature!==JSON.stringify([t,data.account,error,busy]))render();}}).catch(e=>{error=e.message;if(isOpen())render();}).finally(()=>polling=false);}
 }
 function joinPrompt(){api.pause();api.modal('<div class="club-welcome"><button class="modal-close" data-close aria-label="Close">×</button><small>LAST HAND / YOUR SEAT IS WAITING</small><h2 id="dialogTitle">PLAY A HAND TOGETHER.</h2><p>Join a neighborhood to see other players, chat and use the six shared blackjack tables. You start with 500 free chips.</p><button id="clubConnect">JOIN SHARED TABLES</button><button data-close>KEEP EXPLORING</button><p class="club-note">Entry is free. No wallet is needed. Arcade cabinets are decorative; blackjack tables are playable.</p></div>',true);document.getElementById('clubConnect').onclick=connect;}
 async function connect(){if(busy)return;busy=true;try{await api.connect();data=null;last=0;}catch(e){api.notify(e.message);}finally{busy=false;}}
 function directory(){api.pause();api.modal('<div class="club-directory"><button class="modal-close" data-close aria-label="Close casino directory">×</button><small>LAST HAND / SIX TABLES. YOUR KIND OF NIGHT.</small><h2 id="dialogTitle">FIND YOUR TABLE.</h2><p>Pick a table to walk there, then press E to take a seat.</p><div class="club-directory-grid">'+TABLES.map(t=>{const live=api.connected()?data?.tables.find(v=>v.id===t.id):null;return '<button data-casino-table="'+t.id+'"><span>'+t.suit+'</span><small>TABLE '+String(t.id).padStart(2,'0')+'</small><strong>'+esc(t.name)+'</strong><em>'+(live?live.seats.length+' / 4 SEATS':'4 SEATS · FREE CHIPS')+'</em><b>WALK TO TABLE →</b></button>';}).join('')+'</div><p class="club-note">Card tables use free play chips. The arcade displays do not accept bets.</p></div>',true);document.querySelectorAll('[data-casino-table]').forEach(b=>b.onclick=()=>{api.close();api.scene().walkTo(Number(b.dataset.casinoTable));});}
 hud.querySelectorAll('[data-club-area]').forEach(b=>b.onclick=()=>api.scene()?.walkTo(b.dataset.clubArea));document.getElementById('clubTables').onclick=directory;document.getElementById('clubJoin').onclick=connect;document.getElementById('clubPhoto').onclick=api.photo;document.getElementById('clubExit').onclick=api.exit;document.getElementById('clubInteract').onclick=interact;
 return {update,open,interact,get data(){return data;}};
}
